#include <stdio.h>

/* teste do desafio dobra-as-notas — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: o teste chama a funcao do aluno e captura o stdout no
   proprio cenario (freopen, fflush, leitura de volta), cada cenario com
   o SEU arquivo. As duas turmas tem notas de pontas diferentes: nenhuma
   saida fixa serve para as duas. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void dobraAsNotas(int primeira, int ultima);

SM_TEST(o_dobro_das_notas_da_turma_a) {
    freopen("sm_saida_1.tmp", "w", stdout);
    dobraAsNotas(10, 2);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o dobro da gaveta 0", linha, "20\n",
              "a nota 10 da primeira gaveta dobra para 20");
    fgets(linha, 80, f);
    checa_str("o dobro da gaveta 1", linha, "16\n",
              "a nota 8 dobra para 16");
    fgets(linha, 80, f);
    checa_str("o dobro da gaveta 2", linha, "12\n",
              "a nota 6 dobra para 12");
    fgets(linha, 80, f);
    checa_str("o dobro da gaveta 3", linha, "18\n",
              "a nota 9 dobra para 18");
    fgets(linha, 80, f);
    checa_str("o dobro da gaveta 4", linha, "4\n",
              "a nota 2 da ultima gaveta dobra para 4");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "sao cinco gavetas: a saida acaba na quinta linha");
    fclose(f);
}

