#include <stdio.h>

void dobraAsNotas(int primeira, int ultima) {
    int notas[5] = {primeira, 8, 6, 9, ultima};
    notas[0] = notas[0] * 2;
    notas[1] = notas[1] * 2;
    notas[2] = notas[2] * 2;
    notas[3] = notas[3] * 2;
    notas[4] = notas[4] * 2;
    printf("%d\n", notas[0]);
    printf("%d\n", notas[1]);
    printf("%d\n", notas[2]);
    printf("%d\n", notas[3]);
    printf("%d\n", notas[4]);
}
